use std::collections::HashMap;
use std::sync::{Arc, Mutex};

/// Role-based access control system for a document management service
/// Roles use explicit privilege level mapping for security
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum Role {
    /// Guest - minimal access
    Guest,
    /// Viewer - can read documents
    Viewer,
    /// Editor - can modify documents  
    Editor,
    /// Admin - full access
    Admin,
}

impl Role {
    /// Returns the privilege level for this role
    /// Higher values mean more privileges
    fn privilege_level(&self) -> u8 {
        match self {
            Role::Guest => 0,
            Role::Viewer => 1,
            Role::Editor => 2,
            Role::Admin => 3,
        }
    }
}

#[derive(Debug, Clone)]
pub struct User {
    pub id: String,
    pub username: String,
    pub role: Role,
    pub active: bool,
}

#[derive(Debug, Clone)]
pub struct Document {
    pub id: String,
    pub title: String,
    pub content: String,
    pub owner_id: String,
    pub min_role_to_read: Role,
    pub min_role_to_write: Role,
}

pub struct DocumentStore {
    documents: Arc<Mutex<HashMap<String, Document>>>,
    users: Arc<Mutex<HashMap<String, User>>>,
}

impl DocumentStore {
    pub fn new() -> Self {
        Self {
            documents: Arc::new(Mutex::new(HashMap::new())),
            users: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    pub fn add_user(&self, user: User) {
        let mut users = self.users.lock().unwrap();
        users.insert(user.id.clone(), user);
    }

    pub fn add_document(&self, doc: Document) {
        let mut docs = self.documents.lock().unwrap();
        docs.insert(doc.id.clone(), doc);
    }

    /// Check if a user's role meets the minimum required role
    /// Returns true if the user has sufficient privileges
    fn check_permission(user_role: &Role, required_role: &Role) -> bool {
        // User's privilege level must be at least as high as required
        user_role.privilege_level() >= required_role.privilege_level()
    }

    /// Validate that user exists and is active
    fn validate_user(&self, user_id: &str) -> Result<User, String> {
        let users = self.users.lock().unwrap();
        match users.get(user_id) {
            Some(user) if user.active => Ok(user.clone()),
            Some(_) => Err("User account is deactivated".to_string()),
            None => Err("User not found".to_string()),
        }
    }

    /// Read a document with authorization check
    pub fn read_document(&self, user_id: &str, doc_id: &str) -> Result<String, String> {
        let user = self.validate_user(user_id)?;
        let docs = self.documents.lock().unwrap();

        match docs.get(doc_id) {
            Some(doc) => {
                if Self::check_permission(&user.role, &doc.min_role_to_read) {
                    Ok(doc.content.clone())
                } else {
                    Err(format!("Insufficient permissions: {:?} < {:?}", user.role, doc.min_role_to_read))
                }
            }
            None => Err("Document not found".to_string()),
        }
    }

    /// Write/update a document with authorization check
    pub fn write_document(&self, user_id: &str, doc_id: &str, new_content: &str) -> Result<(), String> {
        let user = self.validate_user(user_id)?;
        let mut docs = self.documents.lock().unwrap();

        match docs.get_mut(doc_id) {
            Some(doc) => {
                if Self::check_permission(&user.role, &doc.min_role_to_write) {
                    doc.content = new_content.to_string();
                    Ok(())
                } else {
                    Err(format!("Insufficient write permissions: {:?} < {:?}", user.role, doc.min_role_to_write))
                }
            }
            None => Err("Document not found".to_string()),
        }
    }

    /// Delete a document - requires Admin role
    pub fn delete_document(&self, user_id: &str, doc_id: &str) -> Result<(), String> {
        let user = self.validate_user(user_id)?;

        if Self::check_permission(&user.role, &Role::Admin) {
            let mut docs = self.documents.lock().unwrap();
            docs.remove(doc_id);
            Ok(())
        } else {
            Err("Only admins can delete documents".to_string())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_privilege_levels() {
        // Verify privilege ordering works as expected
        assert!(Role::Admin.privilege_level() > Role::Guest.privilege_level());
        assert!(Role::Editor.privilege_level() > Role::Viewer.privilege_level());
        assert!(Role::Viewer.privilege_level() > Role::Guest.privilege_level());
    }

    #[test]
    fn test_access_control() {
        let store = DocumentStore::new();

        store.add_user(User {
            id: "u1".to_string(),
            username: "admin_user".to_string(),
            role: Role::Admin,
            active: true,
        });

        store.add_user(User {
            id: "u2".to_string(),
            username: "guest_user".to_string(),
            role: Role::Guest,
            active: true,
        });

        store.add_document(Document {
            id: "d1".to_string(),
            title: "Secret Doc".to_string(),
            content: "TOP SECRET DATA".to_string(),
            owner_id: "u1".to_string(),
            min_role_to_read: Role::Admin,
            min_role_to_write: Role::Admin,
        });

        // Admin can read
        assert!(store.read_document("u1", "d1").is_ok());
        // Guest cannot read admin-only doc
        assert!(store.read_document("u2", "d1").is_err());
    }
}
